SELECT eixo_1.no_modalidade AS no_modalidade,   eixo_1.nome_do_curso AS nome_do_curso,   SUM(CAST(eixo_1.number of records AS BIGINT)) AS sum:number of records:ok FROM eixo_1 WHERE ((eixo_1.no_modalidade = 'Pronatec Brasil sem Miséria') AND (NOT ((eixo_1.nome da sit matricula (situacao detalhada) NOT IN ('', 'TRANSF_EXT', 'INTEGRALIZADA', 'FREQ_INIC_INSUF', 'TRANCADA', 'CONCLUÍDA', 'TRANSF_INT', 'EM_CURSO', 'REPROVADA', 'ABANDONO', 'CONFIRMADA', 'EM_DEPENDÊNCIA')) OR (eixo_1.nome da sit matricula (situacao detalhada) IS NULL))) AND (NOT (eixo_1.situacao_da_turma IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY eixo_1.no_modalidade,   eixo_1.nome_do_curso;
